 EditText num(String hint,int mins){EditText e=new EditText(this);e.setHint(hint);e.setText(String.format(java.util.Locale.US,"%02d%02d",mins/60,mins%60));e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setGravity(Gravity.CENTER);e.setBackground(bg(Color.WHITE));if(c!=null)e.setTypeface(c);return e;}int parse(EditText e,int def){try{String x=e.getText().toString().trim();if(x.length()!=4)return def;int h=Integer.parseInt(x.substring(0,2)),m=Integer.parseInt(x.substring(2));if(h<0||h>23||m<0||m>59)return def;return h*60+m;}catch(Exception ex){return def;}}String fmt(int m){return String.format(java.util.Locale.US,"%02d:%02d",m/60,m%60);}void add(View x){LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,dp(58));q.setMargins(0,dp(7),0,0);r.addView(x,q);}
